    subscriptions: [['active', 'Aktiv'], ['trialing', 'Testphase'], ['complimentary', 'Kostenlos'], ['incomplete', 'Unvollständig'], ['past_due', 'Überfällig'], ['canceled', 'Gekündigt']],
