function toast(message: string) { noticeText.value = message; window.setTimeout(() => noticeText.value = '', 3500); }
function queryString() {
    const params = new URLSearchParams(); Object.entries(filters).forEach(([key, value]) => value !== '' && params.set(key, String(value)));
    const secondaryKeys: Record<string, string> = { users: 'role', subscriptions: 'provider', domains: 'type', ai: 'locale', classifications: 'source' };
    if (secondaryKeys[section.value] && filters.secondary) params.set(secondaryKeys[section.value], filters.secondary); return params.toString();
}
async function load() {
    error.value = '';
    try {
        me.value ||= await api('/me'); if (!me.value.user?.is_super_admin) return router.push('/login');
        const url = endpoint[section.value] || endpoint.dashboard;
        if (section.value === 'plans') {
            const [plans, catalog] = await Promise.all([api(url), api('/control/plan-entitlements')]);
            data.value = plans; entitlementCatalog.value = catalog;
        } else data.value = await api(serverSections.has(section.value) ? `${url}?${queryString()}` : url);
        if (section.value === 'settings') hydrateSettings();
        if (['tenants', 'ai', 'templates'].includes(section.value)) {
            const [plans, taxonomy] = await Promise.all([api<any[]>('/control/plans'), api<any>('/control/taxonomy')]);
            lookups.value = { plans, categories: taxonomy.categories, variations: taxonomy.categories.flatMap((category: any) => category.variations) };
        }
    } catch (exception: any) { error.value = exception.message; if (String(exception.message).includes('Unauthenticated')) router.push('/login'); }
}
function resetFilters() { Object.assign(filters, { search: '', status: '', secondary: '', sort: sortOptions[section.value]?.[0]?.[0] || 'created_at', direction: 'desc', per_page: 25, page: 1 }); }
let debounce: number | undefined;
watch(section, () => { selectedTenant.value = null; modal.value = ''; resetFilters(); data.value = null; load(); });
watch(filters, () => { if (!serverSections.has(section.value)) return; window.clearTimeout(debounce); debounce = window.setTimeout(load, 280); }, { deep: true });
onMounted(load);

const catalogRows = computed(() => {
    if (section.value === 'plans') return (data.value || []).map((item: any) => ({ ...item, label: item.name?.de || item.code }));
    if (section.value === 'templates') {
        const categories = (data.value?.categories || []).map((item: any) => ({ ...item, kind: 'category', label: item.name?.de || item.code }));
        const variations = (data.value?.categories || []).flatMap((category: any) => category.variations.map((item: any) => ({ ...item, kind: 'variation', categoryLabel: category.name?.de || category.code, label: item.name?.de || item.code, sort_order: item.priority })));
        const templates = (data.value?.templates || []).map((item: any) => ({ ...item, kind: 'template', label: item.name?.de || item.code })); return [...categories, ...variations, ...templates];
    }
    if (section.value === 'content') return (data.value?.pages || []).map((item: any) => ({ ...item, kind: 'page', label: item.title?.de || item.key }));
    if (section.value === 'backups') return data.value?.backups || []; return [];
});
const localFiltered = computed(() => {
    let result = [...catalogRows.value]; const term = filters.search.toLowerCase().trim(); if (term) result = result.filter((row: any) => JSON.stringify(row).toLowerCase().includes(term));
    if (filters.status) result = result.filter((row: any) => filters.status === 'active' ? (row.enabled ?? row.is_active ?? row.is_published) : !(row.enabled ?? row.is_active ?? row.is_published));
    if (filters.secondary) result = result.filter((row: any) => row.kind === filters.secondary); const key = filters.sort;
    result.sort((a: any, b: any) => String(a[key] ?? '').localeCompare(String(b[key] ?? ''), 'de', { numeric: true })); if (filters.direction === 'desc') result.reverse(); return result;
});
const localPageRows = computed(() => localFiltered.value.slice((filters.page - 1) * filters.per_page, filters.page * filters.per_page));
const rows = computed(() => serverSections.has(section.value) ? (data.value?.data || []) : localPageRows.value);
const pager = computed(() => serverSections.has(section.value) ? { current: data.value?.current_page || 1, last: data.value?.last_page || 1, from: data.value?.from, to: data.value?.to, total: data.value?.total || 0 } : { current: filters.page, last: Math.max(1, Math.ceil(localFiltered.value.length / filters.per_page)), from: localFiltered.value.length ? (filters.page - 1) * filters.per_page + 1 : 0, to: Math.min(filters.page * filters.per_page, localFiltered.value.length), total: localFiltered.value.length });
const entitlementGroups = computed(() => Object.entries(entitlementCatalog.value.groups || {}).map(([key, label]) => ({ key, label, items: Object.entries(entitlementCatalog.value.definitions || {}).filter(([, definition]: any) => definition.group === key).map(([itemKey, definition]) => ({ key: itemKey, ...(definition as any) })) })));
function changePage(page: number) { filters.page = Math.max(1, Math.min(page, pager.value.last)); }
function defaultEntitlements() { return Object.fromEntries(Object.entries(entitlementCatalog.value.definitions || {}).map(([key, definition]: any) => [key, String(definition.default ?? 0)])); }
function resetPlanForm() { Object.assign(planForm, { code: '', name: { de: '', en: '', ru: '', uk: '' }, description: { de: '', en: '', ru: '', uk: '' }, badge_text: { de: '', en: '', ru: '', uk: '' }, price_monthly: 19, price_yearly: 190, currency: 'EUR', prices: { EUR: { monthly: 19, yearly: 190 }, RUB: { monthly: 1990, yearly: 19900 }, UAH: { monthly: 890, yearly: 8900 } }, trial_days: 0, is_active: true, is_public: true, sort_order: 50, entitlements: defaultEntitlements() }); planLocale.value = 'de'; }
function openAdd() { if (section.value === 'tenants') modal.value = 'tenant'; if (section.value === 'plans') { editingPlanId.value = null; resetPlanForm(); modal.value = 'plan'; } if (section.value === 'templates') modal.value = 'catalog'; if (section.value === 'ai') modal.value = 'phrase'; }
async function submit(action: () => Promise<any>, success: string) { busy.value = true; error.value = ''; try { await action(); modal.value = ''; toast(success); await load(); } catch (exception: any) { error.value = exception.message; } finally { busy.value = false; } }
async function createTenant() { await submit(() => api('/control/tenants', { method: 'POST', body: JSON.stringify(tenantForm) }), 'Kunde wurde angelegt.'); }
async function savePlan() { planForm.currency = 'EUR'; planForm.price_monthly = planForm.prices.EUR.monthly; planForm.price_yearly = planForm.prices.EUR.yearly; await submit(() => api(editingPlanId.value ? `/control/plans/${editingPlanId.value}` : '/control/plans', { method: editingPlanId.value ? 'PUT' : 'POST', body: JSON.stringify(planForm) }), 'Tarif wurde gespeichert.'); }
function editPlan(plan: any) { editingPlanId.value = plan.id; Object.assign(planForm, { ...plan, name: { de: '', en: '', ru: '', uk: '', ...plan.name }, description: { de: '', en: '', ru: '', uk: '', ...(plan.description || {}) }, badge_text: { de: '', en: '', ru: '', uk: '', ...(plan.badge_text || {}) }, prices: { EUR: { monthly: Number(plan.prices?.EUR?.monthly ?? plan.price_monthly), yearly: Number(plan.prices?.EUR?.yearly ?? plan.price_yearly) }, RUB: { monthly: Number(plan.prices?.RUB?.monthly ?? 0), yearly: Number(plan.prices?.RUB?.yearly ?? 0) }, UAH: { monthly: Number(plan.prices?.UAH?.monthly ?? 0), yearly: Number(plan.prices?.UAH?.yearly ?? 0) } }, entitlements: { ...defaultEntitlements(), ...Object.fromEntries(plan.entitlements.map((item: any) => [item.key, item.value])) } }); planLocale.value = 'de'; modal.value = 'plan'; }
async function translatePlan() {
    const source = planLocale.value; if (!planForm.name[source]?.trim()) { error.value = 'Bitte zuerst den Tarifnamen in der gewählten Ausgangssprache eingeben.'; return; }
    translating.value = true; error.value = '';
    try {
        const translated = await api<any>('/control/plans/translate', { method: 'POST', body: JSON.stringify({ source_locale: source, name: planForm.name[source], description: planForm.description[source] || '', badge_text: planForm.badge_text[source] || '' }) });
        Object.assign(planForm.name, translated.name); Object.assign(planForm.description, translated.description); Object.assign(planForm.badge_text, translated.badge_text); toast('KI-Übersetzungen wurden eingefügt. Bitte vor dem Speichern prüfen.');
    } catch (exception: any) { error.value = exception.message; } finally { translating.value = false; }
}
function activeEntitlements(plan: any) { return plan.entitlements?.filter((item: any) => entitlementCatalog.value.definitions?.[item.key]?.type === 'boolean' && String(item.value) === '1').length || 0; }
async function saveCatalog() {
    if (catalogKind.value === 'category') return submit(() => api('/control/categories', { method: 'POST', body: JSON.stringify(categoryForm) }), 'Kategorie wurde angelegt.');
    if (catalogKind.value === 'variation') return submit(() => api('/control/variations', { method: 'POST', body: JSON.stringify(variationForm) }), 'Variante wurde angelegt.');
    const payload = { ...templateForm, configuration: JSON.parse(templateForm.configuration) }; return submit(() => api('/control/templates', { method: 'POST', body: JSON.stringify(payload) }), 'Vorlage wurde angelegt.');
}
function choosePhraseVariation() { const variation = lookups.value.variations.find((item: any) => item.id === phraseForm.variation_id); phraseForm.category_id = variation?.category_id || null; }
async function savePhrase() { choosePhraseVariation(); await submit(() => api('/control/phrases', { method: 'POST', body: JSON.stringify(phraseForm) }), 'Begriff wurde hinzugefügt.'); }
async function togglePhrase(item: any) { await api(`/control/phrases/${item.id}`, { method: 'PUT', body: JSON.stringify({ ...item, enabled: !item.enabled, category_id: item.category_id, variation_id: item.variation_id }) }); await load(); }
async function toggleCatalog(item: any) { const path = item.kind === 'category' ? `categories/${item.id}` : item.kind === 'variation' ? `variations/${item.id}` : `templates/${item.id}/toggle`; const body = item.kind === 'template' ? { enabled: !item.enabled } : { ...item, enabled: !item.enabled }; await api(`/control/${path}`, { method: 'PUT', body: JSON.stringify(body) }); await load(); }
async function openTenant(item: any) { try { selectedTenant.value = await api(`/control/tenants/${item.id}`); } catch (exception: any) { error.value = exception.message; selectedTenant.value = null; } }
async function updateTenant(payload: any) { busy.value = true; try { await api(`/control/tenants/${selectedTenant.value.id}`, { method: 'PUT', body: JSON.stringify(payload) }); selectedTenant.value = await api(`/control/tenants/${selectedTenant.value.id}`); await load(); toast('Kunde wurde aktualisiert.'); } finally { busy.value = false; } }
async function saveOverride() { await api(`/control/tenants/${selectedTenant.value.id}/entitlement`, { method: 'PUT', body: JSON.stringify(overrideForm) }); toast('Leistung wurde gespeichert.'); }
async function impersonate() { await api(`/control/tenants/${selectedTenant.value.id}/impersonate`, { method: 'POST' }); location.href = '/app'; }
function askConfirmation(config: any) { confirmAction.value = config; modal.value = 'confirm'; }
async function executeConfirmed() {
    if (!confirmAction.value) return; busy.value = true; error.value = '';
    try { await confirmAction.value.run(); modal.value = ''; confirmAction.value = null; await load(); }
    catch (exception: any) { error.value = exception.message; }
    finally { busy.value = false; }
}
function toggleUser(user: any) {
    askConfirmation({
        title: user.is_active ? 'Benutzer sperren?' : 'Benutzer aktivieren?',
        message: user.is_active ? `${user.name} kann sich danach nicht mehr anmelden.` : `${user.name} erhält wieder Zugriff auf das Kundenkonto.`,
        confirmLabel: user.is_active ? 'Benutzer sperren' : 'Benutzer aktivieren',
        danger: user.is_active,
        run: async () => { await api(`/control/users/${user.id}`, { method: 'PUT', body: JSON.stringify({ is_active: !user.is_active }) }); toast(user.is_active ? 'Benutzer wurde gesperrt.' : 'Benutzer wurde aktiviert.'); },
    });
}
function resetPassword(user: any) {
    askConfirmation({
        title: 'Zugangslink versenden?',
        message: `Ein Link zum Festlegen eines neuen Passworts wird an ${user.email} gesendet.`,
        confirmLabel: 'Link versenden',
        run: async () => { await api(`/control/users/${user.id}/password-reset`, { method: 'POST' }); toast('Link zum Zurücksetzen wurde versendet.'); },
    });
}
async function domainAction(domain: any, action: string) { await api(`/control/domains/${domain.id}/${action}`, { method: 'POST' }); await load(); }
async function deleteDomain(domain: any) { if (!confirm(`${domain.domain} wirklich löschen?`)) return; await api(`/control/domains/${domain.id}`, { method: 'DELETE' }); await load(); }
async function syncPlan(plan: any) { await submit(() => api(`/control/plans/${plan.id}/stripe-sync`, { method: 'POST' }), 'Tarif wurde mit Stripe synchronisiert.'); }
async function syncAllPlans() { await submit(() => api('/control/stripe/sync-plans', { method: 'POST' }), 'Alle Tarife wurden synchronisiert.'); }
async function backupAction(action: string, name?: string) { if (action === 'delete' && !confirm(`${name} wirklich löschen?`)) return; await submit(() => api(name ? `/control/backups/${name}${action === 'verify' ? '/verify' : ''}` : '/control/backups', { method: action === 'delete' ? 'DELETE' : 'POST' }), action === 'create' ? 'Backup wurde erstellt.' : action === 'verify' ? 'Backup ist vollständig.' : 'Backup wurde gelöscht.'); }
function applyPageTranslation(page: any, translated: any) {
    page.title = { de: '', en: '', ru: '', uk: '', ...(page.title || {}), ...(translated.title || {}) };
    page.content = { de: '', en: '', ru: '', uk: '', ...(page.content || {}), ...(translated.content || {}) };
}
function editPage(page: any) {
    selectedPage.value = JSON.parse(JSON.stringify(page));
    if (pageTranslationDrafts[page.id]) applyPageTranslation(selectedPage.value, pageTranslationDrafts[page.id]);
    contentLocale.value = 'de'; modal.value = 'page';
}
function closePageEditor() { modal.value = ''; }
async function openPageTranslationResult() {
    if (!pageTranslation.pageId || pageTranslation.phase !== 'ready') return;
    if (section.value !== 'content') await router.push('/control/content');
    if (!data.value?.pages) data.value = await api('/control/settings');
    const page = data.value.pages.find((item: any) => Number(item.id) === pageTranslation.pageId);
    if (page) editPage(page);
}
async function savePage() {
    busy.value = true; error.value = '';
    try {
        const pageId = Number(selectedPage.value.id);
        await api(`/control/pages/${pageId}`, { method: 'PUT', body: JSON.stringify({ title: selectedPage.value.title, content: selectedPage.value.content, is_published: selectedPage.value.is_published }) });
        delete pageTranslationDrafts[pageId];
        if (pageTranslation.pageId === pageId) Object.assign(pageTranslation, { phase: 'idle', pageId: null, pageKey: '', message: '' });
        modal.value = ''; toast('Inhalt wurde veröffentlicht.'); await load();
    } catch (exception: any) { error.value = exception.message; }
    finally { busy.value = false; }
}
async function translatePage() {
    const source = contentLocale.value;
    if (!selectedPage.value?.title?.[source]?.trim()) { error.value = 'Bitte zuerst den Titel in der gewählten Ausgangssprache eingeben.'; return; }
    const pageId = Number(selectedPage.value.id); const pageKey = String(selectedPage.value.key);
    const payload = { source_locale: source, title: selectedPage.value.title[source], content: selectedPage.value.content[source] || '' };
    translating.value = true; error.value = '';
    Object.assign(pageTranslation, { phase: 'running', pageId, pageKey, message: '' });
    try {
        const translated = await api<any>('/control/pages/translate', { method: 'POST', body: JSON.stringify(payload) });
        pageTranslationDrafts[pageId] = translated;
        if (selectedPage.value?.id === pageId) applyPageTranslation(selectedPage.value, translated);
        Object.assign(pageTranslation, { phase: 'ready', message: 'Die Übersetzung ist fertig. Bitte öffnen, prüfen und speichern.' });
        toast('KI-Übersetzung ist fertig. Öffnen, prüfen und speichern.');
    } catch (exception: any) {
        error.value = exception.message;
        Object.assign(pageTranslation, { phase: 'error', message: exception.message });
    } finally { translating.value = false; }
}
function hydrateSettings() {
    const values = data.value?.settings || {};
    Object.assign(settingForm, values, {
        enabled_locales: [...(values.enabled_locales || ['de', 'en', 'ru', 'uk'])],
        integrations: { stripe: true, openai: true, sms: false, ...(values.integrations || {}) },
        sms_events: { request_received: true, master_replied: true, work_ready: true, agreement_reminder: true, ...(values.sms_events || {}) },
        sms_seven_api_key: '', sms_seven_signing_key: '', sms_clear_api_key: false, sms_clear_signing_key: false,
    });
}
async function saveSettings() { await submit(() => api('/control/settings', { method: 'PUT', body: JSON.stringify({ settings: settingForm }) }), 'Einstellungen wurden gespeichert.'); }
async function uploadPlatformMedia(event: Event, kind: 'image' | 'video') {
    const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return;
    busy.value = true; error.value = '';
    try {
        const body = new FormData(); body.append('file', file);
        const result = await api<any>('/control/content-media', { method: 'POST', body });
        if (kind === 'image') settingForm.social_share_image_url = result.url;
        else { settingForm.demo_video_source = 'upload'; settingForm.demo_video_url = result.url; }
        toast(kind === 'image' ? 'Vorschaubild wurde hochgeladen. Bitte Einstellungen speichern.' : 'Demo-Video wurde hochgeladen. Bitte Einstellungen speichern.');
    } catch (exception: any) { error.value = exception.message; }
    finally { busy.value = false; input.value = ''; }
}
async function testSmsConnection() {
    busy.value = true;
    error.value = '';
    try {
        const result = await api<any>('/control/sms/test', { method: 'POST' });
        const balance = result.balance;
        toast(`seven.io verbunden · Guthaben ${Number(balance.amount).toFixed(2)} ${balance.currency}`);
    } catch (exception: any) {
        error.value = exception.message;
    } finally {
        busy.value = false;
    }
}
async function logout() { await api('/logout', { method: 'POST' }); router.push('/login'); }
function formatDate(value: string | null) { return value ? new Intl.DateTimeFormat('de-DE', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; }
</script>

<template>
<div class="control-shell"><aside class="control-sidebar"><div class="control-wordmark"><b>LOOK</b><span>DO</span><small>SUPER ADMIN</small></div><nav><RouterLink v-for="item in nav" :key="item[0]" :to="`/control/${item[0]}`" :class="{ active: section === item[0] }"><span>{{ item[1] }}</span>{{ item[2] }}</RouterLink></nav><button class="sidebar-logout" @click="logout">Abmelden</button></aside>
<main class="control-main"><header class="control-header"><div><p class="eyebrow">LOOKDO VERWALTUNG</p><h1>{{ nav.find(item => item[0] === section)?.[2] }}</h1></div><div class="admin-chip"><span>SA</span><div><b>{{ me?.user?.name }}</b><small>{{ me?.user?.email }}</small></div></div></header><aside v-if="pageTranslation.phase !== 'idle'" class="translation-job" :class="pageTranslation.phase" role="status" aria-live="polite"><span class="translation-job-icon">{{ pageTranslation.phase === 'ready' ? '✓' : pageTranslation.phase === 'error' ? '!' : '✦' }}</span><div><b>{{ pageTranslation.phase === 'running' ? `KI übersetzt /${pageTranslation.pageKey}` : pageTranslation.phase === 'ready' ? `KI-Übersetzung für /${pageTranslation.pageKey} ist fertig` : `KI-Übersetzung für /${pageTranslation.pageKey} ist fehlgeschlagen` }}</b><small v-if="pageTranslation.phase === 'running'">Das Bearbeitungsfenster darf geschlossen werden. Bitte diesen Browser-Tab geöffnet lassen.</small><small v-else>{{ pageTranslation.message }}</small></div><button v-if="pageTranslation.phase === 'ready'" type="button" @click="openPageTranslationResult">Ergebnis öffnen</button><button v-else-if="pageTranslation.phase === 'error'" type="button" @click="Object.assign(pageTranslation, { phase: 'idle', pageId: null, pageKey: '', message: '' })">Ausblenden</button></aside><p v-if="error" class="alert error">{{ error }}</p><p v-if="noticeText" class="admin-toast">{{ noticeText }}</p><div v-if="!data" class="loading">Wird geladen…</div>
<template v-else><section v-if="section === 'dashboard'" class="admin-dashboard">
<div class="admin-metrics"><RouterLink v-for="metric in data.metrics" :key="metric.key" :to="metric.to"><span>{{ metricLabels[metric.key] || metric.key }}</span><strong>{{ metric.key === 'mrr' ? `${Number(metric.value).toFixed(2)} €` : metric.value }}</strong><small>Öffnen →</small></RouterLink></div>
<div class="admin-dashboard-columns"><section class="admin-dashboard-panel"><div class="dashboard-panel-head"><div><p class="eyebrow">HEUTE</p><h2>Zu erledigen</h2></div><span>{{ data.tasks.length }}</span></div><div v-if="data.tasks.length" class="admin-task-list"><RouterLink v-for="task in data.tasks" :key="task.key" :to="task.to" :class="`severity-${task.severity}`"><i>{{ task.count }}</i><span><b>{{ task.title }}</b><small>{{ task.description }}</small></span><em>→</em></RouterLink></div><div v-else class="dashboard-empty">Keine offenen Pflichtaufgaben. Die Plattform ist vollständig eingerichtet.</div></section>
<section class="admin-dashboard-panel"><div class="dashboard-panel-head"><div><p class="eyebrow">AKTUELL</p><h2>Neueste Aktivitäten</h2></div><RouterLink to="/control/audit">Alle →</RouterLink></div><div class="admin-activity-list"><RouterLink v-for="activity in data.recent" :key="activity.id" :to="activity.to"><span><b>{{ activity.title }}</b><small>{{ activity.description }}</small></span><time>{{ formatDate(activity.created_at) }}</time></RouterLink></div></section></div></section>
<section v-else-if="section === 'settings'" class="human-settings"><form @submit.prevent="saveSettings"><section class="settings-panel"><div class="settings-panel-head"><p class="eyebrow">BETREIBER & RECHTLICHES</p><h2>Rechtliche Angaben und Kontakte</h2><p>Diese Angaben werden automatisch in Impressum, Datenschutz und Kontakt eingesetzt.</p></div><div class="settings-form-grid"><label>Unternehmen / Betreiber<input v-model="settingForm.legal_operator_name"></label><label>Vertretungsberechtigte Person<input v-model="settingForm.legal_representative"></label><label class="wide">Anschrift<textarea v-model="settingForm.legal_operator_address" rows="3"></textarea></label><label>E-Mail<input v-model="settingForm.legal_email" type="email"></label><label>Telefon<input v-model="settingForm.legal_phone" type="tel"></label><label>Handelsregister<input v-model="settingForm.legal_register"></label><label>USt-IdNr.<input v-model="settingForm.legal_vat_id"></label></div></section>
<section class="settings-panel"><div class="settings-panel-head"><p class="eyebrow">PLATTFORM</p><h2>Allgemeine Parameter</h2><p>Klare Felder statt technischer Schlüssel.</p></div><div class="settings-form-grid"><label>Plattformname<input v-model="settingForm.platform_name" required></label><label>Support-E-Mail<input v-model="settingForm.support_email" type="email"></label><label>Standardsprache<select v-model="settingForm.default_locale"><option v-for="locale in planLocales" :key="locale[0]" :value="locale[0]">{{ locale[1] }}</option></select></label><label>Standardvorlage<select v-model="settingForm.default_request_template_code"><option v-for="template in data.templates" :key="template.code" :value="template.code">{{ template.name?.de || template.code }}</option></select></label><label>Standard-Testtage<input v-model.number="settingForm.trial_days_default" type="number" min="0" max="365"></label><label>Upload-Limit pro Datei (MB)<input v-model.number="settingForm.upload_base_limit_mb" type="number" min="1" max="2048"></label></div></section>
<section class="settings-panel media-settings"><div class="settings-panel-head"><p class="eyebrow">FREIGABE & DEMO</p><h2>Vorschaubild und Demo-Video</h2><p>Das Vorschaubild erscheint beim Teilen von lookdo.app in WhatsApp und sozialen Netzwerken. Das Demo-Video öffnet sich über „Beispiel ansehen“; ohne Video scrollt die Schaltfläche nur zur Erklärung.</p></div><div class="platform-media-grid"><article><h3>Social-Media-Vorschaubild</h3><p>Empfohlen: Querformat 1200 × 630 Pixel, JPG, PNG oder WebP.</p><img v-if="settingForm.social_share_image_url" :src="settingForm.social_share_image_url" alt="Aktuelles Vorschaubild"><label class="media-file-button"><input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="uploadPlatformMedia($event, 'image')"><span>{{busy?'Wird hochgeladen…':'Bild hochladen'}}</span></label></article><article><h3>Demo-Video</h3><label>Quelle<select v-model="settingForm.demo_video_source"><option value="none">Kein Video</option><option value="upload">Hochgeladene Datei</option><option value="youtube">YouTube</option></select></label><label v-if="settingForm.demo_video_source==='youtube'">YouTube-URL<input v-model="settingForm.demo_video_url" placeholder="https://www.youtube.com/watch?v=…"></label><template v-if="settingForm.demo_video_source==='upload'"><video v-if="settingForm.demo_video_url" :src="settingForm.demo_video_url" controls preload="metadata"></video><label class="media-file-button"><input type="file" accept="video/mp4,video/webm,video/quicktime" :disabled="busy" @change="uploadPlatformMedia($event, 'video')"><span>{{busy?'Wird hochgeladen…':'Video hochladen'}}</span></label></template></article></div></section><section class="settings-panel sms-settings"><div class="settings-panel-head"><p class="eyebrow">SMS-GATEWAY</p><h2>SMS an Endkunden</h2><p>SMS werden ausschließlich bei aktivierten wichtigen Ereignissen und nur innerhalb des jeweiligen Tariflimits versendet. Es gibt keine automatische Abrechnung bei Überschreitung.</p></div><div class="settings-form-grid"><label>Anbieter<select v-model="settingForm.sms_provider"><option v-for="provider in data.sms.providers" :key="provider.value" :value="provider.value">{{ provider.label }}</option></select></label><label>Absender<input v-model="settingForm.sms_sender" maxlength="16" placeholder="LOOKDO"><small>Maximal 11 alphanumerische oder 16 numerische Zeichen.</small></label><label>seven.io API-Key<input v-model="settingForm.sms_seven_api_key" type="password" autocomplete="new-password" :placeholder="data.sms.api_key_configured ? 'Gespeichert – leer lassen, um beizubehalten' : 'API-Key eintragen'"><small>{{ data.sms.api_key_configured ? 'API-Key ist verschlüsselt gespeichert.' : 'Noch kein API-Key gespeichert.' }}</small></label><label>seven.io Signing Key<input v-model="settingForm.sms_seven_signing_key" type="password" autocomplete="new-password" :placeholder="data.sms.signing_key_configured ? 'Gespeichert – leer lassen, um beizubehalten' : 'Signing Key eintragen'"><small>{{ data.sms.signing_key_configured ? 'Signing Key ist verschlüsselt gespeichert.' : 'Für sichere Delivery-Reports erforderlich.' }}</small></label><label class="wide">Delivery-Webhook<input :value="data.sms.webhook_url" readonly><small>In seven.io als JSON-Webhook für das Ereignis DLR eintragen.</small></label><label class="check"><input v-model="settingForm.sms_clear_api_key" type="checkbox"> Gespeicherten API-Key löschen</label><label class="check"><input v-model="settingForm.sms_clear_signing_key" type="checkbox"> Gespeicherten Signing Key löschen</label></div><div class="sms-event-settings"><h3>Wichtige Ereignisse</h3><div class="settings-choice-grid"><label class="settings-toggle"><input v-model="settingForm.sms_events.request_received" type="checkbox"><span><b>Anfrage erhalten</b><small>Bestätigung für den Endkunden.</small></span></label><label class="settings-toggle"><input v-model="settingForm.sms_events.master_replied" type="checkbox"><span><b>Meister hat geantwortet</b><small>Hinweis mit Link zur Antwort.</small></span></label><label class="settings-toggle"><input v-model="settingForm.sms_events.work_ready" type="checkbox"><span><b>Arbeit fertig</b><small>Benachrichtigung über die Fertigstellung.</small></span></label><label class="settings-toggle"><input v-model="settingForm.sms_events.agreement_reminder" type="checkbox"><span><b>Vereinbarung erinnern</b><small>Erinnerung an Termin oder Absprache.</small></span></label></div></div><div class="settings-panel-actions"><span>Neue Schlüssel zuerst speichern, danach kann die Verbindung geprüft werden.</span><button type="button" class="button ghost" :disabled="busy || !data.sms.api_key_configured" @click="testSmsConnection">seven.io-Verbindung prüfen</button></div></section><section class="settings-panel"><div class="settings-panel-head"><p class="eyebrow">BETRIEB</p><h2>Verfügbarkeit und Funktionen</h2></div><div class="settings-choice-grid"><fieldset><legend>Plattformstatus</legend><label class="settings-toggle"><input v-model="settingForm.registration_enabled" type="checkbox"><span><b>Registrierung geöffnet</b><small>Neue Kunden können ein Konto anlegen.</small></span></label><label class="settings-toggle warning"><input v-model="settingForm.maintenance" type="checkbox"><span><b>Wartungsmodus</b><small>Die Plattform wird vorübergehend eingeschränkt.</small></span></label></fieldset><fieldset><legend>Integrationen</legend><label class="settings-toggle"><input v-model="settingForm.integrations.stripe" type="checkbox"><span><b>Stripe</b><small>Online-Zahlungen und Abonnements.</small></span></label><label class="settings-toggle"><input v-model="settingForm.integrations.openai" type="checkbox"><span><b>OpenAI</b><small>Klassifizierung, Texte und Übersetzungen.</small></span></label><label class="settings-toggle"><input v-model="settingForm.integrations.sms" type="checkbox"><span><b>SMS</b><small>Wichtige Nachrichten an Endkunden über den gewählten Anbieter.</small></span></label></fieldset><fieldset><legend>Verfügbare Sprachen</legend><label v-for="locale in planLocales" :key="locale[0]" class="settings-toggle"><input v-model="settingForm.enabled_locales" type="checkbox" :value="locale[0]"><span><b>{{ locale[1] }}</b></span></label></fieldset></div></section><div class="settings-save-bar"><span>Änderungen gelten nach dem Speichern für die gesamte Plattform.</span><button class="button" :disabled="busy">Einstellungen speichern</button></div></form></section>
<section v-else-if="section === 'stripe'" class="stripe-status"><article><p class="eyebrow">VERBINDUNG</p><h2>{{ data.configured ? 'Stripe verbunden' : 'Stripe nicht konfiguriert' }}</h2><p v-if="data.account">{{ data.account.id }} · {{ data.account.livemode ? 'Live-Modus' : 'Testmodus' }} · {{ data.account.country }}</p></article><article><p class="eyebrow">WEBHOOK</p><h2>{{ data.webhook_configured ? 'Bereit' : 'Fehlt' }}</h2><p>{{ data.plans_pending }} Tarife warten auf Synchronisierung.</p></article><button class="button" :disabled="busy || !data.configured" @click="syncAllPlans">Tarife synchronisieren</button></section>
<section v-else class="admin-section registry-page"><div v-if="section === 'sms'" class="sms-summary"><article><span>Versendet im Monat</span><strong>{{ data.summary?.sent || 0 }}</strong></article><article><span>Zugestellt</span><strong>{{ data.summary?.delivered || 0 }}</strong></article><article><span>Fehlgeschlagen</span><strong>{{ data.summary?.failed || 0 }}</strong></article><article><span>Kosten im Monat</span><strong>{{ Number(data.summary?.cost || 0).toFixed(2) }} {{ data.summary?.currency || 'EUR' }}</strong></article></div><RegistryToolbar v-model:search="filters.search" :total="pager.total" :add-label="addLabels[section]" :busy="busy" @add="openAdd" @refresh="load">
<select v-if="section === 'templates'" v-model="filters.secondary"><option value="">Alle Typen</option><option value="category">Kategorien</option><option value="variation">Varianten</option><option value="template">Vorlagen</option></select>
<select v-else-if="section === 'subscriptions'" v-model="filters.secondary"><option value="">Alle Anbieter</option><option value="stripe">Stripe</option><option value="manual">Manuell</option></select><select v-else-if="section === 'domains'" v-model="filters.secondary"><option value="">Alle Typen</option><option value="platform">Plattform</option><option value="custom">Eigene Domain</option></select><select v-else-if="section === 'ai'" v-model="filters.secondary"><option value="">Alle Sprachen</option><option value="de">Deutsch</option><option value="en">Englisch</option><option value="ru">Russisch</option><option value="uk">Ukrainisch</option></select><select v-else-if="section === 'classifications'" v-model="filters.secondary"><option value="">Alle Quellen</option><option value="dictionary">Wörterbuch</option><option value="fuzzy">Ähnlichkeit</option><option value="ai">KI</option><option value="fallback">Standard</option></select>
<select v-if="statusOptions[section]" v-model="filters.status"><option value="">Alle Status</option><option v-for="option in statusOptions[section]" :key="option[0]" :value="option[0]">{{ option[1] }}</option></select><select v-model="filters.sort"><option v-for="option in sortOptions[section] || []" :key="option[0]" :value="option[0]">{{ option[1] }}</option></select><button type="button" class="sort-direction" @click="filters.direction = filters.direction === 'asc' ? 'desc' : 'asc'">{{ filters.direction === 'asc' ? '↑' : '↓' }}</button><select v-model.number="filters.per_page"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></RegistryToolbar>
<div class="admin-table-wrap"><table><thead v-if="section === 'tenants'"><tr><th>Kunde</th><th>Inhaber</th><th>Vorlage</th><th>Domain</th><th>Tarif</th><th>Status</th></tr></thead><tbody v-if="section === 'tenants'"><tr v-for="item in rows" :key="item.id" class="clickable" @click="openTenant(item)"><td><b>{{ item.name }}</b><small>{{ item.slug }}</small></td><td>{{ item.users?.[0]?.email || '—' }}</td><td>{{ item.business_profile?.variation?.name?.de || item.business_profile?.variation?.code || 'Standard' }}</td><td>{{ item.primary_domain?.domain || '—' }}</td><td>{{ item.current_subscription?.plan?.name?.de || item.current_subscription?.plan?.code || '—' }}</td><td><span class="table-status" :class="item.status">{{ item.status === 'active' ? 'aktiv' : item.status }}</span></td></tr></tbody>
<thead v-if="section === 'users'"><tr><th>Benutzer</th><th>Kunde</th><th>Rolle</th><th>Letzte Anmeldung</th><th>Status</th><th>Aktionen</th></tr></thead><tbody v-if="section === 'users'"><tr v-for="item in rows" :key="item.id"><td><b>{{ item.name }}</b><small>{{ item.email }}</small></td><td>{{ item.tenants?.map((tenant:any) => tenant.name).join(', ') || '—' }}</td><td>{{ item.tenants?.[0]?.pivot?.role === 'owner' ? 'Inhaber' : 'Benutzer' }}</td><td>{{ formatDate(item.last_login_at) }}</td><td>{{ item.is_active ? 'aktiv' : 'gesperrt' }}</td><td class="table-actions"><button :class="{ danger: item.is_active }" @click="toggleUser(item)">{{ item.is_active ? 'Sperren' : 'Aktivieren' }}</button><button @click="resetPassword(item)">Zugang senden</button></td></tr></tbody>
<thead v-if="section === 'administrators'"><tr><th>Administrator</th><th>Rolle</th><th>Letzte Anmeldung</th><th>Seit</th><th>Status</th></tr></thead><tbody v-if="section === 'administrators'"><tr v-for="item in rows" :key="item.id"><td><b>{{ item.name }}</b><small>{{ item.email }}</small></td><td>Super Administrator</td><td>{{ formatDate(item.last_login_at) }}</td><td>{{ formatDate(item.created_at) }}</td><td>{{ item.is_active ? 'aktiv' : 'gesperrt' }}</td></tr></tbody>
<thead v-if="section === 'subscriptions'"><tr><th>Kunde</th><th>Tarif</th><th>Anbieter</th><th>Status</th><th>Periodenende</th><th>Rabatt</th><th>Provider-ID</th></tr></thead><tbody v-if="section === 'subscriptions'"><tr v-for="item in rows" :key="item.id"><td><b>{{ item.tenant?.name }}</b><small>{{ item.tenant?.slug }}</small></td><td>{{ item.plan?.name?.de || item.plan?.code }}</td><td>{{ item.provider === 'manual' ? 'Manuell' : item.provider }}</td><td>{{ item.complimentary ? 'kostenlos' : item.status }}</td><td>{{ formatDate(item.current_period_end) }}</td><td>{{ item.discount_percent }}%</td><td><small>{{ item.provider_subscription_id || '—' }}</small></td></tr></tbody>
<thead v-if="section === 'plans'"><tr><th>Tarif</th><th>Monat</th><th>Jahr</th><th>Module</th><th>Kunden</th><th>Sichtbarkeit</th><th>Stripe</th><th>Aktionen</th></tr></thead><tbody v-if="section === 'plans'"><tr v-for="item in rows" :key="item.id"><td><b>{{ item.name?.de || item.code }}</b><small>{{ item.code }}</small></td><td>{{ item.price_monthly }} {{ item.currency }}</td><td>{{ item.price_yearly || '—' }} {{ item.currency }}</td><td>{{ activeEntitlements(item) }} aktiv</td><td>{{ item.subscriptions_count }}</td><td>{{ item.is_active ? (item.is_public ? 'öffentlich' : 'intern') : 'archiviert' }}</td><td>{{ item.stripe_synced_at ? 'synchron' : (item.stripe_sync_error || 'offen') }}</td><td class="table-actions"><button @click="editPlan(item)">Bearbeiten</button><button @click="syncPlan(item)">Stripe</button></td></tr></tbody>
<thead v-if="section === 'domains'"><tr><th>Domain</th><th>Kunde</th><th>Typ</th><th>DNS</th><th>SSL</th><th>Geprüft</th><th>Aktionen</th></tr></thead><tbody v-if="section === 'domains'"><tr v-for="item in rows" :key="item.id"><td><b>{{ item.domain }}</b></td><td>{{ item.tenant?.name }}</td><td>{{ item.type === 'custom' ? 'Eigene Domain' : 'Plattform' }}</td><td>{{ item.status }}</td><td>{{ item.ssl_status || '—' }}</td><td>{{ formatDate(item.last_checked_at) }}</td><td class="table-actions"><button v-if="item.type === 'custom'" @click="domainAction(item, 'verify')">Prüfen</button><button v-if="item.status === 'ssl_pending'" @click="domainAction(item, 'activate')">Aktivieren</button><button v-if="item.type === 'custom' && item.status === 'active'" @click="domainAction(item, 'disable')">Deaktivieren</button><button v-if="item.type === 'custom' && item.status !== 'active'" class="danger" @click="deleteDomain(item)">Löschen</button></td></tr></tbody>
<thead v-if="section === 'templates'"><tr><th>Typ</th><th>Name</th><th>Code</th><th>Kategorie / Eltern</th><th>Priorität / Version</th><th>Status</th><th>Aktion</th></tr></thead><tbody v-if="section === 'templates'"><tr v-for="item in rows" :key="`${item.kind}-${item.id}`"><td>{{ item.kind === 'category' ? 'Kategorie' : item.kind === 'variation' ? 'Variante' : 'Vorlage' }}</td><td><b>{{ item.label }}</b></td><td><code>{{ item.code }}</code></td><td>{{ item.categoryLabel || item.parent_code || '—' }}</td><td>{{ item.kind === 'template' ? `v${item.version}` : (item.priority ?? item.sort_order) }}</td><td>{{ item.enabled ? 'aktiv' : 'inaktiv' }}</td><td class="table-actions"><button @click="toggleCatalog(item)">{{ item.enabled ? 'Deaktivieren' : 'Aktivieren' }}</button></td></tr></tbody>
<thead v-if="section === 'ai'"><tr><th>Begriff</th><th>Sprache</th><th>Kategorie</th><th>Variante</th><th>Gewichtung</th><th>Status</th><th>Aktion</th></tr></thead><tbody v-if="section === 'ai'"><tr v-for="item in rows" :key="item.id"><td><b>{{ item.phrase }}</b><small>{{ item.normalized_phrase }}</small></td><td>{{ item.locale.toUpperCase() }}</td><td>{{ item.category?.name?.de || item.category?.code }}</td><td>{{ item.variation?.name?.de || item.variation?.code || 'Standard' }}</td><td>{{ item.weight }}</td><td>{{ item.enabled ? 'aktiv' : 'inaktiv' }}</td><td class="table-actions"><button @click="togglePhrase(item)">{{ item.enabled ? 'Deaktivieren' : 'Aktivieren' }}</button></td></tr></tbody>
<thead v-if="section === 'classifications'"><tr><th>Datum</th><th>Eingabe</th><th>Kunde</th><th>Ergebnis</th><th>Sicherheit</th><th>Quelle</th><th>Bestätigt</th></tr></thead><tbody v-if="section === 'classifications'"><tr v-for="item in rows" :key="item.id"><td>{{ formatDate(item.created_at) }}</td><td><b>{{ item.original_text }}</b><small>{{ item.normalized_text }}</small></td><td>{{ item.tenant?.name || 'Registrierung' }}</td><td>{{ item.category?.name?.de || item.category?.code || 'Standard' }}<small>{{ item.variation?.name?.de || item.variation?.code || 'allgemein' }}</small></td><td>{{ Math.round(Number(item.confidence) * 100) }}%</td><td>{{ item.source }}<small>{{ item.ai_model }}</small></td><td>{{ item.confirmed_by_user_at ? 'ja' : 'nein' }}</td></tr></tbody>
<thead v-if="section === 'content'"><tr><th>Seite</th><th>URL</th><th>Status</th><th>Geändert</th><th>Aktion</th></tr></thead><tbody v-if="section === 'content'"><tr v-for="item in rows" :key="item.id"><td><b>{{ item.label }}</b><small>{{ item.title?.ru || item.title?.en }}</small></td><td><code>/{{ item.key }}</code></td><td>{{ item.is_published ? 'veröffentlicht' : 'Entwurf' }}</td><td>{{ formatDate(item.updated_at) }}</td><td class="table-actions"><button @click="editPage(item)">Bearbeiten</button></td></tr></tbody>
<thead v-if="section === 'backups'"><tr><th>Backup</th><th>Erstellt</th><th>Dateien</th><th>Aktionen</th></tr></thead><tbody v-if="section === 'backups'"><tr v-for="item in rows" :key="item.name"><td><b>{{ item.name }}</b></td><td>{{ formatDate(item.created_at) }}</td><td>{{ Object.keys(item.files || {}).length }}</td><td class="table-actions"><button @click="backupAction('verify', item.name)">Prüfen</button><button class="danger" @click="backupAction('delete', item.name)">Löschen</button></td></tr></tbody>
<thead v-if="section === 'sms'"><tr><th>Datum</th><th>Kunde</th><th>Ereignis</th><th>Empfänger</th><th>Status</th><th>Teile</th><th>Kosten</th><th>Provider-ID / Fehler</th></tr></thead><tbody v-if="section === 'sms'"><tr v-for="item in rows" :key="item.id"><td>{{ formatDate(item.created_at) }}</td><td><b>{{ item.tenant?.name || '—' }}</b><small>{{ item.tenant?.slug }}</small></td><td>{{ smsEventLabels[item.event_type] || item.event_type }}</td><td>{{ item.recipient_masked }}</td><td><span class="table-status" :class="item.status">{{ smsStatusLabels[item.status] || item.status }}</span><small>{{ item.provider_status }}</small></td><td>{{ item.parts }}</td><td>{{ Number(item.cost || 0).toFixed(4) }} {{ item.currency }}</td><td><small>{{ item.provider_message_id || item.error_message || '—' }}</small></td></tr></tbody><thead v-if="section === 'audit'"><tr><th>Datum</th><th>Aktion</th><th>Benutzer</th><th>Kunde</th><th>Objekt</th><th>IP-Adresse</th></tr></thead><tbody v-if="section === 'audit'"><tr v-for="item in rows" :key="item.id"><td>{{ formatDate(item.created_at) }}</td><td><b>{{ item.action }}</b></td><td>{{ item.actor_id || 'System' }}</td><td>{{ item.tenant_id || '—' }}</td><td>{{ item.subject_type ? `${item.subject_type.split('\\').pop()} #${item.subject_id}` : '—' }}</td><td>{{ item.ip_address || '—' }}</td></tr></tbody><tbody v-if="!rows.length"><tr><td colspan="9" class="empty-table">Keine passenden Einträge gefunden.</td></tr></tbody></table></div>
<div v-if="section === 'administrators'" class="registry-context"><span>Super-Administratoren werden aus Sicherheitsgründen ausschließlich über den geschützten Serverbefehl angelegt. Kundenbenutzer können hier nicht zu Administratoren gemacht werden.</span></div><div v-if="section === 'backups'" class="registry-context"><span>Speicherort: {{ data.path }}</span><span>Aufbewahrung: {{ data.keep }}</span><button class="button" :disabled="busy" @click="backupAction('create')">＋ Backup erstellen</button></div><AdminPagination :current="pager.current" :last="pager.last" :from="pager.from" :to="pager.to" :total="pager.total" @change="changePage" /></section></template></main>
<aside v-if="selectedTenant" class="drawer"><button class="drawer-close" @click="selectedTenant = null">×</button><p class="eyebrow">KUNDE #{{ selectedTenant.id }}</p><h2>{{ selectedTenant.name }}</h2><p>{{ selectedTenant.slug }}.lookdo.app</p><dl><div><dt>Inhaber</dt><dd>{{ selectedTenant.users?.[0]?.email }}</dd></div><div><dt>Tarif</dt><dd>{{ selectedTenant.current_subscription?.plan?.name?.de || '—' }}</dd></div><div><dt>Status</dt><dd>{{ selectedTenant.status }}</dd></div></dl><button class="button full" @click="impersonate">Kundenkonto öffnen</button><div class="drawer-actions"><button class="button ghost" @click="updateTenant({ status: selectedTenant.status === 'active' ? 'suspended' : 'active' })">{{ selectedTenant.status === 'active' ? 'Sperren' : 'Aktivieren' }}</button></div><template v-if="selectedTenant.current_subscription"><h3>Tarif ändern</h3><select v-model.number="selectedTenant.current_subscription.plan_id"><option v-for="plan in lookups.plans" :key="plan.id" :value="plan.id">{{ plan.name.de || plan.code }}</option></select><button class="button ghost small" @click="updateTenant({ plan_id: selectedTenant.current_subscription.plan_id, complimentary: selectedTenant.current_subscription.complimentary, discount_percent: selectedTenant.current_subscription.discount_percent })">Tarif speichern</button></template><p v-else class="alert">Für diesen Kunden ist noch kein Tarif hinterlegt.</p><h3>Leistung überschreiben</h3><input v-model="overrideForm.key" placeholder="Schlüssel"><input v-model="overrideForm.value" placeholder="Wert"><button class="button ghost small" @click="saveOverride">Speichern</button><h3>Domains</h3><p v-for="domain in selectedTenant.domains" :key="domain.id">{{ domain.domain }} · {{ domain.status }}</p></aside>
<AdminModal v-if="modal === 'tenant'" title="Kunden anlegen" wide @close="modal = ''"><form class="modal-form form-grid" @submit.prevent="createTenant"><label>Unternehmen<input v-model="tenantForm.name" required></label><label>Subdomain<input v-model="tenantForm.slug" placeholder="automatisch"></label><label>Name des Inhabers<input v-model="tenantForm.owner_name" required></label><label>E-Mail des Inhabers<input v-model="tenantForm.owner_email" type="email" required></label><label>Temporäres Passwort<input v-model="tenantForm.owner_password" type="password" minlength="10" required></label><label>Tarif<select v-model.number="tenantForm.plan_id" required><option :value="null">Bitte wählen</option><option v-for="plan in lookups.plans" :key="plan.id" :value="plan.id">{{ plan.name.de || plan.code }}</option></select></label><label>Geschäftsvorlage<select v-model.number="tenantForm.variation_id"><option :value="null">Standardvorlage</option><option v-for="variation in lookups.variations" :key="variation.id" :value="variation.id">{{ variation.name.de || variation.code }}</option></select></label><label class="check"><input v-model="tenantForm.complimentary" type="checkbox"> Kostenlos</label><label class="wide">Tätigkeitsbeschreibung<textarea v-model="tenantForm.business_description"></textarea></label><div class="modal-actions wide"><button type="button" class="button ghost" @click="modal = ''">Abbrechen</button><button class="button" :disabled="busy">Kunden anlegen</button></div></form></AdminModal>
<AdminModal v-if="modal === 'plan'" :title="editingPlanId ? 'Tarif bearbeiten' : 'Tarif anlegen'" wide @close="modal = ''">
  <form class="modal-form form-grid plan-editor" @submit.prevent="savePlan">
    <section class="plan-editor-section wide"><h3>Abrechnung & Veröffentlichung</h3><p>Monats- und Jahrespreise werden je Währung fest hinterlegt. So kann ein Jahrespreis einen eigenen Rabatt enthalten, ohne automatische Wechselkursberechnung.</p><div class="plan-currency-grid"><fieldset v-for="currency in ['EUR','RUB','UAH']" :key="currency" class="plan-currency-card"><legend>{{ currency }}</legend><label>Monatspreis<input v-model.number="planForm.prices[currency].monthly" type="number" min="0" step="0.01" required></label><label>Jahrespreis<input v-model.number="planForm.prices[currency].yearly" type="number" min="0" step="0.01" required></label></fieldset></div><div class="form-grid plan-publishing"><label>Code<input v-model="planForm.code" required></label><label>Testtage<input v-model.number="planForm.trial_days" type="number" min="0"></label><label>Reihenfolge<input v-model.number="planForm.sort_order" type="number" min="0"></label><label class="check"><input v-model="planForm.is_active" type="checkbox"> Aktiv</label><label class="check"><input v-model="planForm.is_public" type="checkbox"> Öffentlich</label></div></section>
    <section class="plan-editor-section wide"><div class="plan-section-head"><div><h3>Texte in vier Sprachen</h3><p>Wählen Sie die Sprache Ihres Ausgangstextes. Die KI übersetzt Name, Beschreibung und Badge in die drei anderen Sprachen.</p></div><button type="button" class="button small" :disabled="translating" @click="translatePlan">{{ translating ? 'KI übersetzt…' : '✦ Mit KI übersetzen' }}</button></div><div class="type-tabs plan-language-tabs"><button v-for="item in planLocales" :key="item[0]" type="button" :class="{ active: planLocale === item[0] }" @click="planLocale = item[0]">{{ item[1] }}<span v-if="planForm.name[item[0]]">✓</span></button></div><div class="form-grid"><label>Tarifname ({{ planLocales.find(item => item[0] === planLocale)?.[1] }})<input v-model="planForm.name[planLocale]" required></label><label>Badge / Kennzeichnung<input v-model="planForm.badge_text[planLocale]" placeholder="z. B. Empfohlen"></label><label class="wide">Beschreibung<textarea v-model="planForm.description[planLocale]" rows="3"></textarea></label></div><p class="plan-translation-note">KI-Texte werden vor dem Speichern in die Felder eingefügt und können manuell geprüft oder geändert werden. Preise, Limits und Leistungen werden nicht von der KI verändert.</p></section>
    <section class="plan-editor-section wide"><h3>Leistungen & Limits</h3><p>Diese Werte steuern die öffentliche Tarifdarstellung und später die Freischaltung der Funktionen im Kundenkonto.</p><div class="entitlement-groups"><fieldset v-for="group in entitlementGroups" :key="group.key" class="entitlement-group"><legend>{{ group.label }}</legend><div class="entitlement-fields"><template v-for="item in group.items" :key="item.key"><label v-if="item.type === 'number'" class="entitlement-number">{{ item.label }}<input v-model="planForm.entitlements[item.key]" type="number" :min="item.min" :max="item.max" required><small v-if="item.help">{{ item.help }}</small></label><label v-else class="check entitlement-check"><input v-model="planForm.entitlements[item.key]" type="checkbox" true-value="1" false-value="0"><span><b>{{ item.label }}</b><small v-if="item.help">{{ item.help }}</small></span></label></template></div></fieldset></div></section>
    <div class="modal-actions wide"><button type="button" class="button ghost" @click="modal = ''">Abbrechen</button><button class="button" :disabled="busy || translating">Tarif speichern</button></div>
  </form>
</AdminModal>
<AdminModal v-if="modal === 'phrase'" title="Geschäftsbegriff hinzufügen" @close="modal = ''"><form class="modal-form" @submit.prevent="savePhrase"><label>Sprache<select v-model="phraseForm.locale"><option value="de">Deutsch</option><option value="en">Englisch</option><option value="ru">Russisch</option><option value="uk">Ukrainisch</option></select></label><label>Variante<select v-model.number="phraseForm.variation_id" required @change="choosePhraseVariation"><option :value="null">Bitte wählen</option><option v-for="variation in lookups.variations" :key="variation.id" :value="variation.id">{{ variation.name.de || variation.name.ru || variation.code }}</option></select></label><label>Begriff<input v-model="phraseForm.phrase" required></label><label>Gewichtung<input v-model.number="phraseForm.weight" type="number" min="0.1" max="5" step="0.1"></label><div class="modal-actions"><button type="button" class="button ghost" @click="modal = ''">Abbrechen</button><button class="button" :disabled="busy">Hinzufügen</button></div></form></AdminModal>
<AdminModal v-if="modal === 'catalog'" title="Vorlagen-Eintrag anlegen" wide @close="modal = ''"><div class="type-tabs"><button v-for="kind in [['category','Kategorie'],['variation','Variante'],['template','Vorlage']]" :key="kind[0]" :class="{ active: catalogKind === kind[0] }" @click="catalogKind = kind[0]">{{ kind[1] }}</button></div><form class="modal-form form-grid" @submit.prevent="saveCatalog"><template v-if="catalogKind === 'category'"><label>Code<input v-model="categoryForm.code" required></label><label>Reihenfolge<input v-model.number="categoryForm.sort_order" type="number"></label><label>Deutsch<input v-model="categoryForm.name.de" required></label><label>Russisch<input v-model="categoryForm.name.ru" required></label></template><template v-if="catalogKind === 'variation'"><label>Kategorie<select v-model.number="variationForm.category_id" required><option v-for="category in lookups.categories" :key="category.id" :value="category.id">{{ category.name.de || category.code }}</option></select></label><label>Code<input v-model="variationForm.code" required></label><label>Deutsch<input v-model="variationForm.name.de" required></label><label>Russisch<input v-model="variationForm.name.ru" required></label><label>Vorlagen-Code<input v-model="variationForm.template_code"></label><label>Priorität<input v-model.number="variationForm.priority" type="number"></label></template><template v-if="catalogKind === 'template'"><label>Kategorie<select v-model.number="templateForm.category_id"><option :value="null">Keine</option><option v-for="category in lookups.categories" :key="category.id" :value="category.id">{{ category.name.de || category.code }}</option></select></label><label>Variante<select v-model.number="templateForm.variation_id"><option :value="null">Keine</option><option v-for="variation in lookups.variations" :key="variation.id" :value="variation.id">{{ variation.name.de || variation.code }}</option></select></label><label>Code<input v-model="templateForm.code" required></label><label>Übergeordneter Code<input v-model="templateForm.parent_code"></label><label>Deutscher Name<input v-model="templateForm.name.de" required></label><label>Version<input v-model.number="templateForm.version" type="number"></label><label class="wide">Konfiguration (JSON)<textarea v-model="templateForm.configuration" rows="10" required></textarea></label></template><div class="modal-actions wide"><button type="button" class="button ghost" @click="modal = ''">Abbrechen</button><button class="button" :disabled="busy">Anlegen</button></div></form></AdminModal>
<AdminModal v-if="modal === 'page' && selectedPage" title="Inhaltsseite bearbeiten" wide @close="closePageEditor"><form class="modal-form" @submit.prevent="savePage"><div class="editor-head"><code>/{{ selectedPage.key }}</code><label class="check"><input v-model="selectedPage.is_published" type="checkbox"> Veröffentlicht</label></div><div class="plan-section-head"><div><p>Ausgangssprache wählen, Text schreiben und anschließend die anderen drei Sprachen mit KI vorbereiten.</p></div><button type="button" class="button small" :disabled="translating" @click="translatePage">{{ translating ? 'KI übersetzt…' : '✦ Mit KI übersetzen' }}</button></div><div v-if="pageTranslation.pageId === selectedPage.id && pageTranslation.phase === 'running'" class="translation-inline working"><span>✦</span><div><b>KI-Übersetzung läuft.</b><small>Dieses Fenster können Sie schließen. Bitte den Browser-Tab geöffnet lassen; das Ergebnis erscheint anschließend oben in der Verwaltung.</small></div></div><div v-else-if="pageTranslation.pageId === selectedPage.id && pageTranslation.phase === 'ready'" class="translation-inline ready"><span>✓</span><div><b>Übersetzung fertig.</b><small>Die Texte wurden als Entwurf eingesetzt. Bitte prüfen und anschließend speichern.</small></div></div><div v-else-if="pageTranslation.pageId === selectedPage.id && pageTranslation.phase === 'error'" class="translation-inline failed"><span>!</span><div><b>Übersetzung fehlgeschlagen.</b><small>{{ pageTranslation.message }}</small></div></div><div class="type-tabs"><button v-for="locale in planLocales" :key="locale[0]" type="button" :class="{ active: contentLocale === locale[0] }" @click="contentLocale = locale[0]">{{ locale[1] }}<span v-if="selectedPage.title[locale[0]]"> ✓</span></button></div><label>Titel<input v-model="selectedPage.title[contentLocale]"></label><label>Inhalt<RichContentEditor v-model="selectedPage.content[contentLocale]" /></label><p class="plan-translation-note">Das Bearbeitungsfenster darf während der Übersetzung geschlossen werden; der Browser-Tab muss geöffnet bleiben. Das Ergebnis wird als Entwurf eingesetzt und erst nach Ihrer Prüfung gespeichert. Platzhalter, Links und HTML bleiben erhalten.</p><div class="modal-actions"><button type="button" class="button ghost" @click="closePageEditor">Schließen</button><button class="button" :disabled="busy || translating">Speichern</button></div></form></AdminModal>
<AdminModal v-if="modal === 'confirm' && confirmAction" :title="confirmAction.title" @close="modal = ''; confirmAction = null"><div class="confirm-dialog"><p>{{ confirmAction.message }}</p><div class="modal-actions"><button type="button" class="button ghost" @click="modal = ''; confirmAction = null">Abbrechen</button><button type="button" class="button" :class="{ danger: confirmAction.danger }" :disabled="busy" @click="executeConfirmed">{{ confirmAction.confirmLabel }}</button></div></div></AdminModal>
</div>
</template>
